-- Changes agents made to computer folders, so the owner can undo them (one row per approved tool call).
CREATE TABLE file_ops(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),call_id uuid UNIQUE REFERENCES tool_calls ON DELETE SET NULL,agent_id uuid REFERENCES agents ON DELETE SET NULL,kind text NOT NULL,items jsonb NOT NULL,undone_at timestamptz,undo_error text,undo_requested_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
-- Long commands running in the background on a computer; the worker follows them and reports when they end.
CREATE TABLE computer_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),computer_key text NOT NULL,computer_name text NOT NULL,computer_id text NOT NULL,remote_id text NOT NULL,call_id uuid REFERENCES tool_calls ON DELETE SET NULL,agent_id uuid REFERENCES agents ON DELETE SET NULL,conversation_id uuid REFERENCES conversations ON DELETE SET NULL,command text NOT NULL,reason text,status text NOT NULL DEFAULT 'running' CHECK(status IN('running','done','failed','cancelled','lost')),exit_code int,output text NOT NULL DEFAULT '',started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz);
CREATE INDEX computer_jobs_running ON computer_jobs(status) WHERE status='running';
